1	import React, { useId } from 'react';
2	import { chakra, Drawer, DrawerOverlay, useMultiStyleConfig, useModalContext, ModalFocusScope } from '@chakra-ui/react';
3	import type { SystemStyleObject } from '@chakra-ui/react';
4	import { motion } from 'framer-motion';
5	import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';
6	import { useUiCopy } from 'app/hooks/useUiCopy';
7	
8	const ZIMM_DRAWER_RECIPE = 'ZimmDrawer';
9	
10	// framer-motion's `Transition.ease` wants a literal, mutable 4-tuple (`BezierDefinition`) — a
11	// plain array literal infers as `number[]`, and `as const` infers a *readonly* tuple, neither of
12	// which satisfies it, hence the explicit cast.
13	const BEZIER_SLIDES_EASING = [0.87, 0, 0.13, 1] as [number, number, number, number];
14	// Mirrors theme/foundation/motion.ts's `duration.default` (300ms) and `easing.slides`
15	// (cubic-bezier(0.87, 0, 0.13, 1), "panels and overlays entering the screen") — hand-converted
16	// to framer-motion's shape (seconds, not ms; a bezier tuple, not a CSS `cubic-bezier()` string)
17	// since motion.ts's tokens are CSS-string form and framer-motion doesn't accept that form. One
18	// shared value for both enter and exit — that symmetry is the whole point (SFCC-898).
19	const DRAWER_TRANSITION = { duration: 0.3, ease: BEZIER_SLIDES_EASING };
20	
21	// `motion(chakra.div)` — framer OUTSIDE, chakra INSIDE. This ordering matters: framer's
22	// `motion()` only intercepts its own known animation props (initial/animate/exit/transition/
23	// variants) and forwards everything else straight to the wrapped component, so `transition`
24	// reaches framer-motion directly here. Chakra's OWN internal Drawer does the reverse
25	// (`chakra(Slide)`) — chakra wraps the animated component — and chakra's `shouldForwardProp`
26	// treats any prop literally named `transition` as a CSS shorthand style prop (it's a real
27	// Chakra/styled-system prop name), silently swallowing it before it ever reaches the wrapped
28	// component's real props (confirmed directly in @chakra-ui/system's should-forward-prop.js).
29	// That's why `<DrawerContent transition={...}>` had no effect and why this file no longer uses
30	// Chakra's `<DrawerContent>` at all — SFCC-898's close-animation defect (asymmetric enter/exit;
31	// Chakra's own Slide defaults to a spring-physics enter vs. a fixed 150ms tween exit, per
32	// @chakra-ui/transition's slide.js) can't be fixed through any prop that component exposes.
33	const MotionChakraDiv = motion(chakra.div);
34	
35	// Matches Figma's own named drawer sizes exactly (SFCC-898) — see zimmDrawer.css.ts's
36	// file-level comment for the width/usage table. `xLarge` has no consumer yet (Cart is a full
37	// page today, not a drawer).
38	export type ZimmDrawerSize = 'large' | 'tablet' | 'small' | 'xLarge' | 'mobile' | 'prompt';
39	
40	type ZimmDrawerBaseProps = {
41	  /** Whether the drawer is open. */
42	  isOpen: boolean;
43	  /** Called on backdrop click, Escape, and the close button (all via Chakra's Drawer). */
44	  onClose: () => void;
45	  /** Desktop/tablet width variant — see ZimmDrawerSize. Collapses to the mobile treatment
46	   *  below the tablet breakpoint regardless of which value is chosen — see zimmDrawer.css.ts. */
47	  size: ZimmDrawerSize;
48	  children: React.ReactNode;
49	  /** Text style for the title. 'large' applies heading1 (24px, uppercase, Futura Round regular);
50	   *  'small' applies body2Strong (14px bold). Defaults to 'large'. Only relevant when `title`
51	   *  is provided. */
52	  titleStyle?: 'large' | 'small';
53	  /** Element to focus when the drawer closes. Use when the trigger may not have received
54	   *  keyboard focus before opening (e.g. mouse click) — without this Chakra falls back to
55	   *  document.body and AC10 focus-return fails. */
56	  finalFocusRef?: React.RefObject<HTMLElement>;
57	  /** Element to focus when the drawer opens. Overrides Chakra's default (first focusable element
58	   *  in the panel, usually the close button) — use to land focus directly on the primary input. */
59	  initialFocusRef?: React.RefObject<HTMLElement>;
60	};
61	
62	/**
63	 * Exactly one of:
64	 * - `title`       — renders an inline header row (title left, close button right); the drawer's
65	 *                   accessible name is derived from the rendered title element automatically.
66	 * - `labelledBy`  — ID of an existing element that labels the drawer (e.g. ZimmPdpDrawer's own
67	 *                   tab header). Paired with the floating close button by default. Pass
68	 *                   `boxedHeader` alongside it when the drawer has no header content of its own
69	 *                   to supply (e.g. ZimmCountryLanguageMismatch, whose heading lives in its body)
70	 *                   but still wants the close button in the same in-flow header row `title` gets,
71	 *                   instead of floating over the content — the title `<span>` renders with no
72	 *                   text, purely to hold the close button's usual right-aligned position. The
73	 *                   drawer's accessible name still comes from `labelledBy`, unaffected.
74	 * - `aria-label`  — explicit string label when neither a visible title nor a separate element
75	 *                   is available.
76	 */
77	type ZimmDrawerProps = ZimmDrawerBaseProps &
78	  (
79	    | { title: string; labelledBy?: never; 'aria-label'?: never; boxedHeader?: never }
80	    | { title?: never; labelledBy: string; 'aria-label'?: never; boxedHeader?: boolean }
81	    | { title?: never; labelledBy?: never; 'aria-label': string; boxedHeader?: never }
82	  );
83	
84	// Deliberately not named `ZimmDrawerContentProps` — scripts/generateRegistry.mjs's
85	// extractTsProps merges every `*Props`-suffixed type in a file into one component's registry
86	// row when it can't isolate the preferred one (ZimmDrawerProps' multi-line union body isn't
87	// matched by its regex, which can't cross a newline — a documented limitation, not a bug to
88	// patch there). That merge was leaking this internal helper's own fields (ariaLabel,
89	// contentStyles, closeButtonStyles) into ZimmDrawer's public registry entry.
90	type ZimmDrawerContentConfig = {
91	  children: React.ReactNode;
92	  onClose: () => void;
93	  /** Renders an inline header row (title left, close button right) instead of the floating
94	   *  close button when provided — see ZimmDrawerProps' `title` member. */
95	  title?: string;
96	  titleId?: string;
97	  titleStyle?: 'large' | 'small';
98	  labelledBy?: string;
99	  ariaLabel?: string;
100	  /** Forces the same in-flow header row `title` renders (empty title span, close button in its
101	   *  usual right-aligned slot) instead of the floating close button — see ZimmDrawerProps'
102	   *  `labelledBy` member. Meaningless without `labelledBy`. */
103	  boxedHeader?: boolean;
104	  contentStyles: SystemStyleObject;
105	  headerStyles: SystemStyleObject;
106	  headerTitleStyles: SystemStyleObject;
107	  closeButtonStyles: SystemStyleObject;
108	};
109	
110	/**
111	 * Replaces Chakra's own `<DrawerContent>` — see the `MotionChakraDiv` comment above for why.
112	 * Reuses Chakra's real dialog/focus/aria mechanics directly (`useModalContext`,
113	 * `ModalFocusScope` — both genuinely public exports, not reaching into Chakra internals) so
114	 * focus trap, initial focus, focus restore, body-scroll lock, and Escape/overlay-click-to-close
115	 * all still come from Chakra exactly as before; only the slide transition itself is now ours.
116	 *
117	 * Renders the inline header row (title left — empty when there's no `title` text — close button
118	 * right) when either `title` or `boxedHeader` is passed, or a floating close button only when
119	 * neither is — see ZimmDrawer's own docblock for when each is used.
120	 *
121	 * @param props see ZimmDrawerContentConfig
122	 */
123	const ZimmDrawerContent = ({
124	  children,
125	  onClose,
126	  title,
127	  titleId,
128	  titleStyle = 'large',
129	  labelledBy,
130	  ariaLabel,
131	  boxedHeader,
132	  contentStyles,
133	  headerStyles,
134	  headerTitleStyles,
135	  closeButtonStyles,
136	}: ZimmDrawerContentConfig) => {
137	  const { t } = useUiCopy();
138	  const { getDialogProps, getDialogContainerProps } = useModalContext();
139	  const dialogProps = getDialogProps({ 'aria-label': ariaLabel });
140	  // getDialogProps always computes `aria-labelledby` from Chakra's own <DrawerHeader> mount
141	  // state, which ZimmDrawer never renders (no header sub-component in this tree) — so it
142	  // always resolves to undefined regardless of what's passed in above. Set it directly so the
143	  // `title` and `labelledBy` prop variants of ZimmDrawerProps actually work.
144	  if (title && titleId) {
145	    dialogProps['aria-labelledby'] = titleId;
146	  } else if (labelledBy) {
147	    dialogProps['aria-labelledby'] = labelledBy;
148	  }
149	  const containerProps = getDialogContainerProps();
150	
151	  return (
152	    <ModalFocusScope>
153	      <chakra.div {...containerProps} __css={{ position: 'fixed', inset: 0, display: 'flex', zIndex: 'modal' }}>
154	        <MotionChakraDiv
155	          {...dialogProps}
156	          initial={{ x: '100%' }}
157	          animate={{ x: 0 }}
158	          exit={{ x: '100%' }}
159	          transition={DRAWER_TRANSITION}
160	          __css={{ position: 'fixed', top: 0, right: 0, bottom: 0, outline: 0, ...contentStyles }}
161	        >
162	          {title || boxedHeader ? (
163	            <chakra.div sx={headerStyles}>
164	              <chakra.span
165	                id={title ? titleId : undefined}
166	                sx={headerTitleStyles}
167	                textStyle={titleStyle === 'small' ? 'body2Strong' : 'heading1'}
168	              >
169	                {title}
170	              </chakra.span>
171	              <ZimmButton variant="icon" icon="close" label={t('drawer.close', 'Close')} onClick={onClose} />
172	            </chakra.div>
173	          ) : (
174	            <chakra.div sx={closeButtonStyles}>
175	              <ZimmButton variant="icon" icon="close" label={t('drawer.close', 'Close')} onClick={onClose} />
176	            </chakra.div>
177	          )}
178	          {children}
179	        </MotionChakraDiv>
180	      </chakra.div>
181	    </ModalFocusScope>
182	  );
183	};
184	
185	/**
186	 * Generic right-anchored slide-in drawer shell — overlay, panel, and a Figma-matched size
187	 * variant (see ZimmDrawerSize), built on Chakra's Drawer primitive (focus trap, initial focus,
188	 * focus restore, body-scroll lock, and Escape/overlay-click-to-close all come from Chakra, not
189	 * hand-rolled).
190	 *
191	 * Pass `title` to render an inline header row (title text left, close button right) sized per the
192	 * Figma drawer/header frames. Omit `title` and pass `labelledBy`/`aria-label` instead for drawers
193	 * that supply their own header (e.g. ZimmPdpDrawer's tab row) — the close button floats on its own
194	 * by default. Add `boxedHeader` alongside `labelledBy` when the drawer has no header content of its
195	 * own (e.g. ZimmCountryLanguageMismatch, whose heading lives in its body) but still wants the close
196	 * button sitting in that same in-flow header row rather than floating over the content.
197	 *
198	 * @param props see ZimmDrawerProps
199	 */
200	export const ZimmDrawer = (props: ZimmDrawerProps) => {
201	  const { isOpen, onClose, size, children, titleStyle = 'large', finalFocusRef, initialFocusRef } = props;
202	  const styles = useMultiStyleConfig(ZIMM_DRAWER_RECIPE, { variant: size });
203	  const titleId = useId();
204	
205	  const title = 'title' in props ? props.title : undefined;
206	  const labelledBy = !title && 'labelledBy' in props ? props.labelledBy : undefined;
207	  const ariaLabel = !title && 'aria-label' in props ? props['aria-label'] : undefined;
208	  const boxedHeader = !title && 'labelledBy' in props ? props.boxedHeader : undefined;
209	
210	  // Chakra's FocusLock remains active during the exit animation, so any focus call made
211	  // while the drawer is still mounted (rAF, close-button onClick) gets trapped and dropped.
212	  // onCloseComplete fires after the animation finishes and FocusLock is released — the only
213	  // reliable moment to restore focus. Covers both close-button click and Escape for all
214	  // consumers that pass finalFocusRef.
215	  const handleCloseComplete = () => {
216	    if (finalFocusRef) finalFocusRef.current?.focus();
217	  };
218	
219	  return (
