const { chromium } = require('/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/@playwright/test');

const STORIES = [
  { id: 'layout-zimmcountrylanguagemismatch--location', name: 'Location' },
  { id: 'layout-zimmcountrylanguagemismatch--language', name: 'Language' },
];

const VIEWPORTS = [
  { name: 'mobile-440x956', width: 440, height: 956 },
  { name: 'tablet-800x1024', width: 800, height: 1024 },
  { name: 'desktop-1440x900', width: 1440, height: 900 },
];

(async () => {
  const browser = await chromium.launch();
  const results = [];
  try {
    for (const vp of VIEWPORTS) {
      for (const story of STORIES) {
        const page = await browser.newPage({ viewport: { width: vp.width, height: vp.height } });
        const url = `http://localhost:6006/iframe.html?id=${story.id}&viewMode=story`;
        await page.goto(url, { waitUntil: 'networkidle' });
        const dialog = page.locator('[role="dialog"]').first();
        await dialog.waitFor({ state: 'visible', timeout: 10000 });
        // let the 300ms framer-motion slide settle
        await page.waitForTimeout(700);
        const dialogBox = await dialog.boundingBox();
        const buttons = dialog.locator('button');
        const count = await buttons.count();
        const lastButton = buttons.nth(count - 1);
        const lastButtonBox = await lastButton.boundingBox();
        const lastButtonText = (await lastButton.innerText()).trim();
        const scrollHeight = await dialog.evaluate((el) => el.scrollHeight);
        const clientHeight = await dialog.evaluate((el) => el.clientHeight);
        const computedBottom = await dialog.evaluate((el) => getComputedStyle(el).bottom);
        const computedHeight = await dialog.evaluate((el) => getComputedStyle(el).height);
        const gapBelow =
          dialogBox && lastButtonBox
            ? dialogBox.y + dialogBox.height - (lastButtonBox.y + lastButtonBox.height)
            : null;
        results.push({
          viewport: vp.name,
          story: story.name,
          panelHeightPx: dialogBox ? Math.round(dialogBox.height * 100) / 100 : null,
          panelYPx: dialogBox ? Math.round(dialogBox.y * 100) / 100 : null,
          computedHeight,
          computedBottom,
          scrollHeight,
          clientHeight,
          lastButtonText,
          gapBelowLastButtonPx: gapBelow !== null ? Math.round(gapBelow * 100) / 100 : null,
          buttonCount: count,
        });
        await page.close();
      }
    }
  } finally {
    await browser.close();
  }
  console.log(JSON.stringify(results, null, 2));
})().catch((e) => {
  console.error('SCRIPT ERROR', e);
  process.exit(1);
});
